from __future__ import annotations

import base64
import gzip
import os
from pathlib import Path

V13_B64 = ''
FINAL2_B64 = ''

PROJECT = Path(os.environ.get("PHOCAP_PROJECT", r"C:\PhoCap")).resolve()
ROUTER = PROJECT / "app" / "routers" / "report_inputs.py"

V12_MARKER = "BAI_13B_6_V1_2_NETWORK_DATA_START"
V13_MARKER = "BAI_13B_6_V1_3_MN_SCOPE_START"


def read_router() -> str:
    if not ROUTER.exists():
        raise RuntimeError(f"Không tìm thấy tệp bắt buộc: {ROUTER}")
    return ROUTER.read_text(encoding="utf-8-sig")


def run_embedded(source_b64: str, name: str) -> int:
    source = gzip.decompress(base64.b64decode(source_b64)).decode("utf-8")
    namespace = {
        "__name__": name,
        "__file__": str(PROJECT / f"_{name}.py"),
    }
    exec(compile(source, namespace["__file__"], "exec"), namespace)

    main_fn = namespace.get("main")
    if not callable(main_fn):
        raise RuntimeError(f"Không tìm thấy main() trong {name}.")

    result = main_fn()
    return int(result or 0)


def main() -> int:
    print("=" * 100)
    print("BÀI 13B-6 V1.4 FINAL-2A - TỰ ĐỘNG BỔ SUNG V1.3 NẾU THIẾU")
    print("=" * 100)
    print("")

    router_text = read_router()

    if V12_MARKER not in router_text:
        print("DỪNG AN TOÀN:")
        print(" - Chưa tìm thấy nền dữ liệu Bài 13B-6 V1.2 FINAL.")
        print(" - Không có tệp nào bị thay đổi bởi FINAL-2A.")
        print("")
        print("Hãy gửi ảnh Terminal này cho ChatGPT.")
        return 2

    if V13_MARKER not in router_text:
        print("Phát hiện máy CHƯA có marker Bài 13B-6 V1.3.")
        print("FINAL-2A sẽ tự cài V1.3 trước, sau đó mới cài FINAL-2.")
        print("")

        result = run_embedded(
            V13_B64,
            "embedded_bai_13b_6_v1_3",
        )
        if result != 0:
            print("")
            print("Cài V1.3 không thành công. FINAL-2 chưa được chạy.")
            return result

        router_text = read_router()
        if V13_MARKER not in router_text:
            print("")
            print("Không xác nhận được marker V1.3 sau khi cài. Dừng an toàn.")
            return 3
    else:
        print("Đã có Bài 13B-6 V1.3 -> bỏ qua bước cài V1.3.")

    print("")
    print("Bắt đầu cài Bài 13B-6 V1.4 FINAL-2...")
    print("")

    result = run_embedded(
        FINAL2_B64,
        "embedded_bai_13b_6_v1_4_final2",
    )
    if result != 0:
        return result

    print("")
    print("=" * 100)
    print("CAI DAT BAI 13B-6 V1.4 FINAL-2A THANH CONG")
    print("=" * 100)
    print(" - Đã bảo đảm nền V1.3.")
    print(" - Đã cài nội dung V1.4 FINAL.")
    print(" - Đã tách Danh mục trường MN / Tiểu học / THCS.")
    print(" - Đã tách TK trường MN / Tiểu học / THCS.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
